<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api, chartUrl, safeDownload } from '../api'
import { state, perform, refresh, label, short, nameOf, time, date, showError } from '../state'
import { scoreFields } from '../types'
import type { Audit, Candidate, Note, RecordData } from '../types'
import ChartPreview from '../components/ChartPreview.vue'
import ProposalPanel from '../components/ProposalPanel.vue'
const props = defineProps<{ selected: string }>()
const emit = defineEmits<{ 'update:selected': [id: string] }>()
const candidate = ref<Candidate | null>(null), audit = ref<Audit | null>(null), history = ref<RecordData>({ versions: [], reviews: [], playtests: [], proposals: [] })
const preview = ref<InstanceType<typeof ChartPreview>>()
const currentTime = ref(0), selectedNote = ref<Note | null>(null), reviewer = ref(''), comment = ref(''), annotation = ref('')
const annotations = ref<{ time_s: number; text: string }[]>([])
const scores = ref<Record<string, number | ''>>(Object.fromEntries(scoreFields.map(f => [f.key, ''])))
const decision = ref('revision_requested'), exportPurpose = ref('local'), includeAudio = ref(true), downloadUrl = ref(''), compareId = ref(''), comparison = ref<RecordData | null>(null)
const playtest = ref({ reviewer: '', engine_version: '', platform: '', passed: false, notes: '' })
const playtestConfirmed = ref(false), loadError = ref(''), auditMessage = ref(''), loading = ref(false)
let loadSequence = 0
const complete = computed(() => scoreFields.every(f => scores.value[f.key] !== '' && Number.isFinite(Number(scores.value[f.key])) && Number(scores.value[f.key]) >= 0 && Number(scores.value[f.key]) <= f.max))
const total = computed(() => complete.value ? Object.values(scores.value).reduce<number>((sum, value) => sum + Number(value), 0).toFixed(1) : '—')
const reviewed = computed(() => candidate.value?.status?.toLowerCase() === 'approved' && history.value.reviews?.some((r: any) => (!r.candidate_id || r.candidate_id === candidate.value?.id) && (!r.chart_sha256 || r.chart_sha256 === candidate.value?.chart_sha256) && r.decision?.toLowerCase() === 'approved'))
const played = computed(() => history.value.playtests?.some((r: any) => (!r.candidate_id || r.candidate_id === candidate.value?.id) && r.passed === true))
const blockers = computed(() => audit.value?.issues?.filter((i: any) => i.severity === 'BLOCK') || [])
const warnings = computed(() => audit.value?.issues?.filter((i: any) => i.severity === 'WARN') || [])
const auditReady = computed(() => !!audit.value && ['PASS', 'WARN'].includes(audit.value.status))
const auditHasRun = computed(() => !!audit.value && ['PASS', 'WARN', 'BLOCK'].includes(audit.value.status))
async function load(id: string) {
  const seq = ++loadSequence; candidate.value = null; audit.value = null; loading.value = true; loadError.value = ''; auditMessage.value = ''; comparison.value = null; selectedNote.value = null; currentTime.value = 0; downloadUrl.value = ''; annotations.value = []; scores.value = Object.fromEntries(scoreFields.map(f => [f.key, ''])); comment.value = ''; decision.value = 'revision_requested'
  if (!id) { loading.value = false; return }
  const results = await Promise.allSettled([api<Candidate>(`/candidates/${id}`), api<Audit>(`/candidates/${id}/audit`), api(`/candidates/${id}/history`)])
  if (seq !== loadSequence) return
  if (results[0]!.status === 'fulfilled') candidate.value = results[0]!.value
  else loadError.value = results[0]!.reason instanceof Error ? results[0]!.reason.message : '无法读取候选。'
  if (results[1]!.status === 'fulfilled') audit.value = results[1]!.value
  else auditMessage.value = results[1]!.reason instanceof Error ? results[1]!.reason.message : '尚无审计报告。'
  if (results[2]!.status === 'fulfilled') history.value = results[2]!.value
  else { history.value = { versions: [], reviews: [], playtests: [], proposals: [] }; showError(results[2]!.reason) }
  loading.value = false
}
watch(() => props.selected, load, { immediate: true })
watch(() => state.candidates, () => { if (!props.selected && state.candidates.length) emit('update:selected', state.candidates[0]!.id) }, { immediate: true })
// A completed audit job refreshes the actual report without discarding unsent human scores.
watch(() => state.jobs.filter(j => /audit/.test(j.kind || j.type || '')).map(j => `${j.id}:${j.state || j.status}`).join('|'), async () => { if (!props.selected) return; try { audit.value = await api(`/candidates/${props.selected}/audit`); auditMessage.value = '' } catch { /* The audit panel retains its current explicit pending state. */ } })
function seek(value?: number) { if (typeof value === 'number') preview.value?.seek(value) }
function mark() { if (!annotation.value.trim()) return; annotations.value.push({ time_s: currentTime.value, text: annotation.value.trim() }); annotation.value = '' }
async function runAudit() { await perform('audit', async () => { await api(`/candidates/${props.selected}/audit`, 'POST', {}); await refresh() }, '独立非 AI 审计已加入任务队列。') }
async function review() { if (!candidate.value || !complete.value) return; await perform('review', async () => { await api(`/candidates/${props.selected}/reviews`, 'POST', { reviewer: reviewer.value.trim(), scores: scores.value, decision: decision.value, comment: comment.value, annotations: annotations.value }); history.value = await api(`/candidates/${props.selected}/history`); candidate.value = await api(`/candidates/${props.selected}`); await refresh() }, '人工审核已保存，并绑定当前候选版本。') }
async function savePlaytest() { await perform('playtest', async () => { await api(`/candidates/${props.selected}/playtests`, 'POST', { ...playtest.value }); history.value = await api(`/candidates/${props.selected}/history`); playtestConfirmed.value = false }, '已登记你提供的真人试玩记录。') }
async function exportZip() { await perform('export', async () => { const r = await api(`/candidates/${props.selected}/exports`, 'POST', { purpose: exportPurpose.value, include_audio: includeAudio.value }); downloadUrl.value = safeDownload(r.download_url) }, '导出包已由本地服务生成。') }
async function revert(id: string) { await perform('revert', async () => { const r = await api(`/candidates/${props.selected}/revert`, 'POST', { target_candidate_id: id }); await refresh(); emit('update:selected', r.candidate_id || r.id) }, '已基于所选内容创建回滚版本，旧历史保留。') }
async function compare() { if (!compareId.value || !candidate.value) return; await perform('compare', async () => { const start = Math.max(0, Math.floor(currentTime.value) - 8), end = start + 30; const [meta, timeline, current] = await Promise.all([api(`/candidates/${compareId.value}`), api(`/candidates/${compareId.value}/timeline?start_s=${start}&end_s=${end}`), api(`/candidates/${candidate.value!.id}/timeline?start_s=${start}&end_s=${end}`)]); const before = new Map<string, any>(timeline.notes.map((n: Note) => [n.id, n])); const after = new Map<string, any>(current.notes.map((n: Note) => [n.id, n])); const fields = ['kind','beat','end_beat','line_id','x','lane_index','above','fake']; const changed = [...after].filter(([id, n]) => before.has(id) && fields.some(k => JSON.stringify(n[k]) !== JSON.stringify(before.get(id)[k]))).map(([id, n]) => ({ id, before: before.get(id), after: n })); comparison.value = { meta, timeline, current, start, end, added: [...after.keys()].filter(id => !before.has(id)).length, removed: [...before.keys()].filter(id => !after.has(id)).length, changed } }) }
async function sendBridge() { await perform('bridge-send', async () => { const r = await api(`/bridge/candidates/${props.selected}/send`, 'POST', { expected_chart_sha256: candidate.value!.chart_sha256 }); return r }, '编辑器发送命令已排队。只有收到保存回执后才表示已保存，请在连接页查看状态。') }
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">HUMAN IN THE LOOP</p><h1>把判断，留给你的耳朵与双手。</h1><p class="subtitle">逐段听音、查看审计证据，为这个版本留下独立的人工记录。</p></div><span class="badge outline">真人审核</span></div>
  <div class="candidate-selector panel"><div class="field"><label for="review-candidate">当前候选谱面</label><select id="review-candidate" :value="selected" @change="emit('update:selected', ($event.target as HTMLSelectElement).value)"><option value="" disabled>选择待审核候选</option><option v-for="c in state.candidates" :key="c.id" :value="c.id">{{ nameOf(c.music_asset_id) }} · {{ label(c.chart_mode) }} {{ c.key_count ? `${c.key_count}K` : '' }} · {{ short(c.id) }} · {{ label(c.status) }}</option></select></div><button class="button secondary" :disabled="!selected || loading" @click="load(selected)">刷新此版本</button></div>
  <div v-if="loading" class="empty panel"><span class="spinner"></span><strong>正在读取候选与审核历史…</strong></div><div v-else-if="loadError" class="panel inline-error">{{ loadError }}</div><div v-else-if="!candidate" class="empty panel"><span class="empty-icon">▤</span><strong>这里等待你的第一份候选</strong><p>生成谱面后，可在这里听音、定位问题与提交审核。</p></div>
  <template v-else>
    <div class="review-version-bar"><div class="row"><span class="badge blue">{{ label(candidate.chart_mode) }} {{ candidate.key_count ? `${candidate.key_count}K` : '' }}</span><h2>{{ nameOf(candidate.music_asset_id) }}</h2><span class="badge">{{ label(candidate.status) }}</span></div><span class="micro muted">版本 {{ short(candidate.id) }} · SHA-256 {{ short(candidate.chart_sha256) }}</span></div>
    <div class="review-layout"><ChartPreview ref="preview" :candidate-id="candidate.id" :music-id="candidate.music_asset_id" @time="currentTime = $event" @select-note="selectedNote = $event" />
      <section class="panel audit-panel"><div class="panel-heading compact"><div><p class="section-kicker">独立非 AI 审计</p><h2>先检查，再评分。</h2></div><span :class="['badge', audit?.status === 'BLOCK' ? 'red' : audit?.status === 'WARN' ? 'amber' : audit ? 'green' : '']">{{ label(audit?.status || '未完成') }}</span></div><div class="audit-counts"><div><strong>{{ auditHasRun ? blockers.length : '—' }}</strong><span>BLOCK 阻断</span></div><div><strong>{{ auditHasRun ? warnings.length : '—' }}</strong><span>WARN 提醒</span></div></div><p class="small-text muted">音频 DSP、数学与几何检验独立于生成模型。点击问题可跳到对应时间。</p><button class="button secondary full" :disabled="state.busy.audit" @click="runAudit">{{ state.busy.audit ? '提交中…' : audit ? '重新运行独立审计' : '运行独立审计' }}</button><p v-if="!auditHasRun" class="soft-callout muted">{{ auditMessage || '当前版本还没有审计报告。正式评分与导出需等待审计完成。' }}</p><div v-else class="issue-list"><button v-for="(issue, i) in audit?.issues || []" :key="i" :class="['issue-card', issue.severity?.toLowerCase()]" @click="seek(issue.time_s)"><div class="row between"><span class="badge" :class="issue.severity === 'BLOCK' ? 'red' : 'amber'">{{ issue.severity }}</span><code>{{ issue.time_s != null ? time(issue.time_s) : '全局检查' }}</code></div><strong>{{ issue.message }}</strong><span>{{ issue.code }}{{ issue.note_id ? ` · 音符 ${issue.note_id}` : '' }}{{ issue.line_id ? ` · 线 ${issue.line_id}` : '' }}</span></button><div v-if="!audit?.issues?.length" class="empty small"><span class="empty-icon">✓</span><strong>此报告没有列出问题</strong><p>自动审计通过仍需真人评判可玩性。</p></div></div><details v-if="audit"><summary>审计指标与引擎版本</summary><p class="micro">{{ audit.engine_version || '版本未提供' }}</p><pre>{{ JSON.stringify(audit.metrics || {}, null, 2) }}</pre></details></section>
    </div>
    <div class="review-lower-layout"><section class="panel"><div class="panel-heading"><div><p class="section-kicker">人工审核记录</p><h2>六个维度，一个真实判断。</h2></div><div class="score-total"><strong>{{ total }}</strong><span>/ 100</span></div></div><p v-if="!auditReady" class="soft-callout amber-callout">{{ audit?.status === 'BLOCK' ? '当前版本存在 BLOCK。可保留问题备注；请修改后重新审计，不能批准本版本。' : '请先完成独立非 AI 审计，再提交正式人工审核。' }}</p><div class="form-grid score-grid"><div v-for="f in scoreFields" :key="f.key" class="field"><label :for="'score-' + f.key">{{ f.key === 'expression' && candidate.chart_mode === 'pure_keys' ? '配置变化与音乐表现' : f.name }}<span class="muted">满分 {{ f.max }}</span></label><input :id="'score-' + f.key" v-model.number="scores[f.key]" type="number" min="0" :max="f.max" step=".5" placeholder="由你填写" :aria-label="f.name"><p class="field-hint">{{ f.hint }}</p></div></div><div class="form-grid"><div class="field"><label>审核人 <span class="required">*</span></label><input v-model="reviewer" placeholder="填写你的名字或本地昵称" maxlength="100"></div><div class="field"><label>审核结论</label><select v-model="decision"><option value="revision_requested">退回修改</option><option value="approved" :disabled="!auditReady">通过</option><option value="rejected">拒绝</option></select></div></div><div class="field"><label>审核意见</label><textarea v-model="comment" rows="3" maxlength="5000" placeholder="记录节奏、手感、可读性与需要修改的地方。"></textarea></div><div class="annotation-entry"><label>时间标记 <code>{{ time(currentTime) }}</code></label><div class="input-action"><input v-model="annotation" placeholder="在当前播放时间留下问题或建议" maxlength="1000" @keydown.enter.prevent="mark"><button class="button secondary" :disabled="!annotation.trim()" @click="mark">＋ 标记</button></div></div><div class="annotation-list"><div v-for="(a, i) in annotations" :key="i"><button class="text-button" @click="seek(a.time_s)">{{ time(a.time_s) }}</button><span>{{ a.text }}</span><button class="icon-button" aria-label="删除此标记" @click="annotations.splice(i,1)">×</button></div></div><div class="form-footer"><span class="muted micro">六项初始为空，仅计算你实际填写的分数。</span><button class="button primary" :disabled="!complete || !reviewer.trim() || !auditHasRun || (decision === 'approved' && !auditReady) || state.busy.review" @click="review">保存人工审核</button></div></section>
    <section class="panel delivery-panel"><div class="panel-heading"><div><p class="section-kicker">导出与试玩</p><h2>带着证据，进入下一步。</h2></div></div><div class="checklist"><div><span :class="auditReady ? 'check-ok' : 'check-wait'">{{ auditReady ? '✓' : '○' }}</span>当前版本无审计阻断</div><div><span :class="reviewed ? 'check-ok' : 'check-wait'">{{ reviewed ? '✓' : '○' }}</span>当前版本人工审核通过</div><div><span :class="played ? 'check-ok' : 'check-wait'">{{ played ? '✓' : '○' }}</span>已登记真实客户端试玩</div></div><div class="field"><label>导出用途</label><select v-model="exportPurpose"><option value="local">本地使用</option><option value="distribution">对外分发（需素材分发许可）</option></select></div><label class="checkbox"><input v-model="includeAudio" type="checkbox" disabled><span>包含音乐文件（当前打包格式必需）</span></label><button class="button primary full" :disabled="!auditReady || !reviewed || !played || state.busy.export" @click="exportZip">{{ state.busy.export ? '正在打包…' : '生成审核版 ZIP' }}</button><a v-if="downloadUrl" class="button secondary full" :href="downloadUrl" download>下载本地 ZIP</a><a class="text-button draft-link" :href="chartUrl(candidate.id)" download>下载未审核 JSON 草稿 ↗</a><p class="field-hint">ZIP 需同版本审核、试玩记录与非 BLOCK 审计；对外分发另检查素材许可。JSON 草稿不代表已通过审核。</p><div class="divider"></div><h3>登记 Phira-Pro 真人试玩</h3><div class="field"><label>试玩人</label><input v-model="playtest.reviewer" placeholder="真人试玩者"></div><div class="form-grid"><div class="field"><label>客户端版本</label><input v-model="playtest.engine_version" placeholder="实际 Phira-Pro 版本"></div><div class="field"><label>设备与平台</label><input v-model="playtest.platform" placeholder="设备 / 系统 / 输入方式"></div></div><div class="field"><label>试玩结果</label><select v-model="playtest.passed"><option :value="false">未通过 / 发现问题</option><option :value="true">真人试玩通过</option></select></div><div class="field"><label>实际观察</label><textarea v-model="playtest.notes" rows="2" placeholder="记录实际导入、操作体验与问题"></textarea></div><label class="checkbox"><input v-model="playtestConfirmed" type="checkbox"><span>我确认这是真实客户端中的人工试玩记录。</span></label><button class="button secondary full" :disabled="!playtestConfirmed || !playtest.reviewer.trim() || !playtest.engine_version.trim() || !playtest.platform.trim() || state.busy.playtest" @click="savePlaytest">保存试玩记录</button><div class="divider"></div><button class="button secondary full" :disabled="!reviewed || state.busy['bridge-send']" @click="sendBridge">发送到已配对的 RPE 编辑器</button><p class="field-hint">需在“连接与设置”中配对，且此版本必须来自该编辑器会话。</p></section></div>
    <section class="panel history-panel"><div class="panel-heading"><div><p class="section-kicker">可追溯的创作</p><h2>版本、审核与试玩历史</h2></div><code class="micro muted">{{ candidate.chart_sha256 }}</code></div><div class="history-layout"><div><h3>不可变版本</h3><div v-for="v in history.versions || []" :key="v.id" :class="['version-row', { current: v.id === candidate.id }]"><div><strong>{{ short(v.id) }}</strong><span class="badge">{{ label(v.status) }}</span><p>{{ date(v.created_at) }} · {{ short(v.chart_sha256) }}</p></div><div class="row"><button class="text-button" @click="emit('update:selected', v.id)">查看</button><button class="text-button" :disabled="state.busy.revert" @click="revert(v.id)">回滚为新版本</button></div></div><p v-if="!history.versions?.length" class="muted small-text">服务尚未提供相关版本记录。</p><div class="field"><label>选择一个版本比较</label><div class="input-action"><select v-model="compareId"><option value="" disabled>选择版本</option><option v-for="v in (history.versions || []).filter((v: any) => v.id !== candidate!.id)" :key="v.id" :value="v.id">{{ short(v.id) }} · {{ date(v.created_at) }}</option></select><button class="button secondary" :disabled="!compareId || state.busy.compare" @click="compare">比较</button></div></div><div v-if="comparison" class="comparison"><p class="field-hint">比较时间窗 {{ time(comparison.start) }}–{{ time(comparison.end) }}。以下差异以稳定音符 ID 匹配。</p><table><thead><tr><th>比较项</th><th>当前版本</th><th>所选版本</th></tr></thead><tbody><tr><td>内容哈希</td><td>{{ short(candidate.chart_sha256) }}</td><td>{{ short(comparison.meta.chart_sha256) }}</td></tr><tr><td>模式</td><td>{{ label(candidate.chart_mode) }}</td><td>{{ label(comparison.meta.chart_mode) }}</td></tr><tr><td>键位数</td><td>{{ candidate.key_count || '自由布局' }}</td><td>{{ comparison.meta.key_count || '自由布局' }}</td></tr><tr><td>当前窗口音符</td><td>{{ comparison.current.notes.length }}</td><td>{{ comparison.timeline.notes.length }}</td></tr><tr><td>窗口内差异</td><td colspan="2">相对所选版本：新增 {{ comparison.added }}，移除 {{ comparison.removed }}，更改 {{ comparison.changed.length }}</td></tr><tr><td>内容相同</td><td colspan="2">{{ candidate.chart_sha256 === comparison.meta.chart_sha256 ? '哈希一致' : '哈希不同，查看条件与局部提案差异' }}</td></tr></tbody></table><details><summary>窗口内音符具体差异</summary><pre>{{ JSON.stringify(comparison.changed, null, 2) }}</pre></details><details><summary>所选版本完整生成条件</summary><pre>{{ JSON.stringify(comparison.meta.conditions, null, 2) }}</pre></details></div></div><div><h3>已保存的人类判断</h3><div v-for="r in history.reviews || []" :key="r.id" class="history-record"><div class="row between"><strong>{{ r.reviewer }}</strong><span class="badge" :class="r.decision === 'approved' ? 'green' : 'amber'">{{ label(r.decision) }} · {{ r.total ?? r.score_total ?? '—' }} 分</span></div><p>{{ r.comment || '未填写意见' }}</p><p class="micro muted">{{ date(r.created_at) }}</p><button v-for="(a,i) in r.annotations || []" :key="i" class="saved-annotation" @click="seek(a.time_s)">{{ time(a.time_s) }} · {{ a.text }}</button></div><p v-if="!history.reviews?.length" class="muted small-text">当前版本还没有人工评分。</p><div v-for="p in history.playtests || []" :key="p.id" class="history-record"><div class="row between"><strong>{{ p.reviewer }} · {{ p.engine_version }}</strong><span :class="['badge', p.passed ? 'green' : 'red']">{{ p.passed ? '试玩通过' : '试玩未通过' }}</span></div><p>{{ p.platform }} · {{ p.notes || '无附加备注' }}</p><p class="micro muted">{{ date(p.created_at) }}</p></div></div></div></section>
    <ProposalPanel :candidate="candidate" :note="selectedNote" :existing="history.proposals || []" @committed="emit('update:selected', $event)" />
  </template>
</template>
